"use client";

import { FolderIcon, PlusSignIcon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import { Button } from "@/components/ui/button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";

export default function ProjectsPage() {
  return (
    <div className="px-6 py-10 flex h-full items-center justify-center min-h-[500px]">
      <div className="mx-auto w-full max-w-lg">
        <Empty className="rounded-xl border bg-muted/20 py-14 shadow-sm">
          <EmptyHeader>
            <EmptyMedia className="rounded-2xl bg-muted/50 p-5 text-muted-foreground mb-4">
              <HugeiconsIcon icon={FolderIcon} size={32} strokeWidth={1.5} />
            </EmptyMedia>
            <EmptyTitle className="text-xl font-bold tracking-tight">
              No Projects Yet
            </EmptyTitle>
            <EmptyDescription className="text-base max-w-[300px]">
              You haven&apos;t created any projects yet. Get started by creating
              your first project to track your work.
            </EmptyDescription>
          </EmptyHeader>
          <EmptyContent>
            <div className="flex flex-wrap gap-2 *:mx-auto">
              <Button size="lg" className="rounded-xl px-8 shadow-sm">
                <HugeiconsIcon
                  icon={PlusSignIcon}
                  className="mr-2"
                  size={20}
                  strokeWidth={2}
                />
                Create Project
              </Button>
            </div>
          </EmptyContent>
        </Empty>
      </div>
    </div>
  );
}
